    parameter CRITICAL_CURRENT_UA = 50,
    parameter SWITCHING_TIME_NS = 2,
    parameter TMR_RATIO = 25,
    parameter ANISOTROPY_FIELD_OE = 500
)(
    input wire clk,
    input wire rst_n,
    input wire [15:0] spin_current_ua,
    input wire [15:0] magnetic_field_oe,
    input wire write_enable,
    output reg magnetization_state,
    output reg [15:0] resistance_ohm,
    output reg switching_complete
);
reg [15:0] switching_counter;
reg switching_in_progress;
reg mag_state_next;
reg [15:0] switching_counter_next;
reg switching_in_progress_next;
reg switching_complete_next;
reg [15:0] resistance_next;
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        magnetization_state <= 1'b0;
        resistance_ohm <= 16'd1000 + (16'd1000 * TMR_RATIO) / 10;
        switching_complete <= 1'b0;
        switching_counter <= 16'd0;
        switching_in_progress <= 1'b0;
    end else begin
        mag_state_next = magnetization_state;
        switching_in_progress_next = switching_in_progress;
        switching_counter_next = switching_counter;
        switching_complete_next = 1'b0;
        if (write_enable && (spin_current_ua > CRITICAL_CURRENT_UA) && !switching_in_progress) begin
            switching_in_progress_next = 1'b1;
            switching_counter_next = 16'd0;
        end
        if (switching_in_progress_next) begin
            switching_counter_next = switching_counter_next + 16'd1;
            if (switching_counter_next >= SWITCHING_TIME_NS) begin
                mag_state_next = ~mag_state_next;
                switching_in_progress_next = 1'b0;
                switching_complete_next = 1'b1;
            end
        end
        resistance_next = mag_state_next ? 16'd1000 : (16'd1000 + (16'd1000 * TMR_RATIO) / 10);
        magnetization_state <= mag_state_next;
        switching_in_progress <= switching_in_progress_next;
        switching_counter <= switching_counter_next;
        switching_complete <= switching_complete_next;
        resistance_ohm <= resistance_next;
    end
end
